const AdminDashboard = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentEventId, setCurrentEventId] = useState(null);
  const [newEvent, setNewEvent] = useState({
    title: "",
    description: "",
    date: "",
    image: null,  // Initially null for both create and edit
  });

  // Fetch Events
  const fetchEvents = async () => {
    try {
      const response = await API.get("/events/admin-events");
      setEvents(response.data);
    } catch (error) {
      console.error("Error fetching events:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  // Show Modal for Creating or Editing Events
  const handleShowModal = (event = null) => {
    if (event) {
      setEditMode(true);
      setCurrentEventId(event._id);
      setNewEvent({
        title: event.title,
        description: event.description,
        date: event.date,
        image: event.image || null,  // Retain the current image or set to null if not available
      });
    } else {
      setEditMode(false);
      setCurrentEventId(null);
      setNewEvent({ title: "", description: "", date: "", image: null });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => setShowModal(false);

  // Handle Input Changes
  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "image") {
      setNewEvent((prevEvent) => ({ ...prevEvent, image: files[0] })); // Update image file
    } else {
      setNewEvent((prevEvent) => ({ ...prevEvent, [name]: value }));  // Update other fields
    }
  };

  // Create or Update Event
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append("title", newEvent.title);
      formData.append("description", newEvent.description);
      formData.append("date", newEvent.date);

      // Append image if available
      if (newEvent.image) {
        formData.append("image", newEvent.image);
      }

      let response;
      if (editMode) {
        // Edit existing event
        response = await API.put(`/events/${currentEventId}`, formData, {
          headers: { "Content-Type": "multipart/form-data" },
        });
      } else {
        // Create new event
        response = await API.post("/events", formData, {
          headers: { "Content-Type": "multipart/form-data" },
        });
      }

      if (response.status === 201 || response.status === 200) {
        fetchEvents(); // Refresh events after creating/updating
        setShowModal(false);
        setNewEvent({ title: "", description: "", date: "", image: null });
      }
    } catch (error) {
      console.error("Error creating/updating event:", error);
    }
  };

  // Delete Event
  const handleDelete = async (eventId) => {
    try {
      await API.delete(`/events/${eventId}`);
      fetchEvents();
    } catch (error) {
      console.error("Error deleting event:", error);
    }
  };

  return (
    <Container className="admin-dashboard-container mt-5">
      <h2 className="text-center mb-4">Admin Dashboard</h2>

      {loading ? (
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      ) : (
        <Table striped bordered hover>
          <thead>
            <tr>
              <th>Title</th>
              <th>Description</th>
              <th>Date</th>
              <th>Image</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {events.map((event) => (
              <tr key={event._id}>
                <td>{event.title}</td>
                <td>{event.description}</td>
                <td>{new Date(event.date).toLocaleDateString()}</td>
                <td>
                  {event.image ? (
                    <img
                      src={`/images/${event.image}`} // Correct image URL for events
                      alt={event.title}
                      width="100"
                      height="100"
                    />
                  ) : (
                    "No Image"
                  )}
                </td>
                <td>
                  <Button
                    variant="warning"
                    onClick={() => handleShowModal(event)}
                    className="me-2"
                  >
                    Edit
                  </Button>
                  <Button variant="danger" onClick={() => handleDelete(event._id)}>
                    Delete
                  </Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}

      <Button variant="primary" onClick={() => handleShowModal()}>
        Create New Event
      </Button>

      {/* Modal for Creating & Editing Events */}
      <Modal show={showModal} onHide={handleCloseModal}>
        <Modal.Header closeButton>
          <Modal.Title>{editMode ? "Edit Event" : "Create New Event"}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleSubmit} encType="multipart/form-data">
            <Form.Group controlId="formTitle">
              <Form.Label>Title</Form.Label>
              <Form.Control
                type="text"
                name="title"
                value={newEvent.title}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group controlId="formDescription" className="mt-3">
              <Form.Label>Description</Form.Label>
              <Form.Control
                type="text"
                name="description"
                value={newEvent.description}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group controlId="formDate" className="mt-3">
              <Form.Label>Date</Form.Label>
              <Form.Control
                type="date"
                name="date"
                value={newEvent.date}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group controlId="formImage" className="mt-3">
              <Form.Label>Image</Form.Label>
              <Form.Control type="file" name="image" onChange={handleChange} />
            </Form.Group>
            <Button variant="primary" type="submit" className="mt-4">
              {editMode ? "Update Event" : "Create Event"}
            </Button>
          </Form>
        </Modal.Body>
      </Modal>
    </Container>
  );
};
